export type PhysicalOrderRole = 'buyer' | 'seller';

export type PhysicalOrder = {
  id: string;
  buyer_id: string;
  seller_id: string;
  listing_id: string;
  role: PhysicalOrderRole;
  status: string;
  payment_status: string;
  vault_status: string;
  shipping_status: string;
  amount?: number;
  total_amount?: number;
  currency?: string;
  created_at: string;
  listing?: { id: string; title: string; type: string; images?: string[]; image_url?: string; thumbnail?: string };
  buyer?: { id: string; username?: string; full_name?: string; avatar_url?: string } | null;
  seller?: { id: string; username?: string; full_name?: string; avatar_url?: string } | null;
  shipment?: Record<string, any> | null;
  reserve?: Record<string, any> | null;
  shippingWizard?: Record<string, any> | null;
  dispute?: Record<string, any> | null;
  deliveryConfirmation?: Record<string, any> | null;
  events?: Array<{ id: string; event_type: string; actor_role: string; metadata?: Record<string, unknown>; created_at: string }>;
};

export const physicalTypeValues = new Set(['physical', 'product', 'pos', 'pos_item']);

export const isPhysicalListingType = (value: unknown) => physicalTypeValues.has(String(value || '').toLowerCase());

export const fulfillmentStage = (order: Pick<PhysicalOrder, 'payment_status' | 'vault_status' | 'shipping_status' | 'dispute'>) => {
  if (order.dispute && !['resolved', 'closed'].includes(String(order.dispute.status))) return 'problem';
  if (order.vault_status === 'released' && order.shipping_status === 'delivered') return 'complete';
  if (order.shipping_status === 'delivered') return 'delivery_confirmed';
  if (['shipped', 'in_transit'].includes(order.shipping_status)) return 'in_transit';
  if (order.vault_status === 'locked' && order.payment_status === 'paid') return 'ready_to_ship';
  if (order.payment_status === 'paid') return 'reserve_pending';
  return 'payment_pending';
};

export const stageCopy: Record<string, { label: string; description: string }> = {
  payment_pending: { label: 'Payment pending', description: 'Waiting for a confirmed provider payment.' },
  reserve_pending: { label: 'Securing payment', description: 'Stripe payment is confirmed; the reserve record is being secured.' },
  ready_to_ship: { label: 'Ready to ship', description: 'Payment is protected. The seller can prepare the package.' },
  in_transit: { label: 'In transit', description: 'The package is on its way to the buyer.' },
  delivery_confirmed: { label: 'Delivery confirmed', description: 'The buyer confirmed receipt; payout processing may still be running.' },
  complete: { label: 'Completed', description: 'Delivery was confirmed and the seller transfer was released.' },
  problem: { label: 'On hold', description: 'A delivery problem is open and the payment reserve remains protected.' },
};

export const formatOrderMoney = (amount: unknown, currency: unknown = 'EUR') => {
  const numeric = Number(amount || 0);
  try {
    return new Intl.NumberFormat('en-NL', { style: 'currency', currency: String(currency || 'EUR').toUpperCase() }).format(numeric);
  } catch {
    return `${numeric.toFixed(2)} ${String(currency || 'EUR').toUpperCase()}`;
  }
};

export const formatShippingAddress = (address: unknown) => {
  if (!address || typeof address !== 'object') return [];
  const row = address as Record<string, unknown>;
  return [
    [row.line1, row.line2].filter(Boolean).join(' '),
    [row.postal_code, row.city].filter(Boolean).join(' '),
    [row.state, row.country].filter(Boolean).join(' '),
  ].filter(Boolean).map(String);
};
